"""Original concept cases. Three learning tasks per case: selection, reasoning,
and multiple-response discrimination. No certification exam questions are used."""
import json, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'backend'))
from app.schemas import QuestionInput, fingerprint
CASES=[]
def case(obj,scenario,correct,reason,wrong,commands=None,difficulty='medium',reference=None):
    assert len(wrong)==3
    CASES.append(dict(obj=obj,scenario=scenario,correct=correct,reason=reason,wrong=wrong,commands=commands or [],difficulty=difficulty,reference=reference))
# Each incorrect option pairs its text with a specific explanation of its error.
case('1.1','A web operations report needs a table of total bytes for each host, with a column for each status code.', 'chart sum(bytes) over host by status','chart aggregates a numeric measure over a row dimension and a split-by column dimension.', [('chart bytes over host by status','bytes is a field, but the chart measure requires an aggregation function.'),('timechart sum(bytes) by status','timechart uses time buckets as its row dimension rather than host.'),('chart count over host by status','count counts events; it does not total bytes.')],['chart'])
case('1.1','A store wants a visualization of total revenue by product; the numeric revenue field is already extracted.','chart sum(revenue) by product','sum(revenue) adds the revenue values within each product group.', [('chart avg(revenue) by product','avg computes mean revenue rather than total revenue.'),('chart count by product','count measures event frequency rather than revenue.'),('chart sum(product) by revenue','This reverses the numeric measure and grouping dimension.')],['chart'])
case('1.2','An analyst needs the number of failed logins in fifteen-minute buckets, one series for each host. The base search already filters failures.','timechart span=15m count by host','timechart automatically groups on _time and span controls the width of the time buckets.', [('chart count by host','This groups by host without a time axis.'),('timechart span=15h count by host','15h means fifteen hours, not fifteen minutes.'),('timechart span=15m sum(host)','host is the grouping field, not a numeric event-count measure.')],['timechart'])
case('1.2','A performance engineer wants hourly mean latency for each service, with latency measured in milliseconds.','timechart span=1h avg(latency) by service','avg(latency) computes the mean inside each hourly bucket and service series.', [('timechart span=1h sum(latency) by service','sum measures cumulative latency, not the mean.'),('stats avg(latency) by service','This loses the hourly timeline.'),('timechart span=1m avg(latency) by service','A one-minute bucket is not hourly.')],['timechart'])
case('1.2','A timeline splits event counts by user. The analyst deliberately wants every user series rather than a top-series limit.','timechart count by user limit=0','For timechart, limit=0 disables split-by series limiting.', [('timechart count by user limit=1','This retains only one split series.'),('timechart count by user span=0','span controls time bucket size, not the number of series.'),('chart count by user','This does not produce the requested time axis.')],['timechart'],'hard')
case('2.1','For an event with bytes=2097152, create a new numeric field mb using 1024-based megabytes.','eval mb=bytes/1024/1024','eval evaluates arithmetic for each result; dividing twice by 1024 produces 2.', [('eval mb=bytes*1024*1024','Multiplication increases the value rather than converting bytes to megabytes.'),('eval mb="bytes/1024/1024"','A quoted expression is a literal string, not arithmetic.'),('where mb=bytes/1024/1024','where filters rows and does not create the field.')],['eval'])
case('2.1','A report needs severity="high" when count exceeds 20 and severity="normal" otherwise.','eval severity=if(count>20,"high","normal")','if evaluates its condition and chooses one of two values for the output field.', [('eval severity=if(count>20,"normal","high")','The true and false labels are reversed.'),('search severity=high','search filters existing values instead of computing labels.'),('eval severity="if(count>20,high,normal)"','This stores a literal expression string instead of evaluating it.')],['eval'])
case('2.1','Combine the extracted user and host fields into a label such as aya@app01.','eval label=user . "@" . host','The period operator concatenates string values in an eval expression.', [('eval label=user + "@" + host','The plus operator performs arithmetic, not string concatenation.'),('eval label="user@host"','This creates a constant rather than interpolating field values.'),('where label=user . "@" . host','where tests a condition; it does not assign a label.')],['eval'])
case('2.1','A login report should use user when present and account otherwise; both can be missing.','eval identity=coalesce(user,account)','coalesce returns the first non-null argument and returns null if none has a value.', [('eval identity=user . account','Concatenation combines text rather than choosing the first non-null value.'),('eval identity=max(user,account)','max is not a first-non-null selection operation.'),('eval identity="user"','The quoted name is a literal rather than the field value.')],['eval'])
case('2.2','Results have elapsed and budget numeric fields. Keep rows whose elapsed exceeds their own budget.','where elapsed>budget','where treats unquoted identifiers as fields and evaluates field-to-field comparisons.', [('search elapsed>budget','search does not provide this eval-style field-to-field comparison.'),('where "elapsed">"budget"','Both operands are literal strings rather than field values.'),('eval exceeded=elapsed-budget','This calculates a field but does not discard rows.')],['where','search'])
case('2.2','After stats count by host, retain only host rows with more than 100 events.','where count>100','The count field exists after aggregation, so a subsequent where filters those aggregated rows.', [('where host>100','host is the grouping value, not the event count.'),('eval count=100','This overwrites counts rather than selecting rows.'),('fillnull value=100 count','fillnull supplies missing values rather than filtering counts.')],['stats','where'])
case('2.2','A post-processing filter should keep users whose name begins with svc. Use an eval-style wildcard expression.','where like(user,"svc%")','like uses percent to match any sequence of characters, so this pattern retains names beginning with svc.', [('where like(user,"svc_*")','like does not use the search asterisk as a sequence wildcard.'),('where user="svc_%"','Equality compares with a literal percent string rather than a like pattern.'),('eval user="svc_%"','This replaces user rather than filtering results.')],['where'],'hard')
case('2.3','Some results lack dest, but another result has dest=app01. Fill only missing dest values with unknown.','fillnull value="unknown" dest','fillnull replaces missing values in the named field and leaves existing values intact.', [('eval dest="unknown"','This replaces every dest value, including app01.'),('fillnull value="unknown" user','This targets user rather than dest.'),('where isnull(dest)','This removes rows with a destination rather than filling missing values.')],['fillnull'])
case('2.3','A count report contains a numeric field failures with some null values and at least one non-null value. Replace its nulls with zero.','fillnull value=0 failures','An explicit field list confines replacement to failures, and value=0 supplies the desired replacement.', [('fillnull value=1 failures','This supplies one instead of zero.'),('search failures=0','This filters existing zeros and does not fill nulls.'),('eval failures=0','This overwrites all existing counts.')],['fillnull'])
case('2.3','A proposed fillnull operation targets a field that has no non-null value in any result. Why should the analyst inspect the result schema first?','A field needs at least one non-null value in the result set for fillnull to recognize it as an existing field','Splunk distinguishes null values in an existing field from a field absent from the result schema.', [('fillnull rewrites the indexed raw events','fillnull operates on search results; it does not rewrite indexed raw events.'),('fillnull requires transaction before it','No transaction prerequisite exists.'),('fillnull is only a chart formatting option','fillnull is a search command that replaces null result values.')],['fillnull'],'hard')
# Correlation: fifteen cases across all six official objectives.
case('3.1','A request is represented by start, intermediate, and end events with the same request_id. The investigator needs them as one grouped result.','Use transaction request_id','transaction combines related events into transaction results and preserves grouped event information.', [('Use chart count by request_id','chart produces aggregate counts rather than grouped raw-event transaction results.'),('Use eval request_id="all"','This destroys the correlation key.'),('Use fillnull request_id','Replacing nulls does not correlate the events.')],['transaction'])
case('3.1','Which identifiers make the strongest transaction key for a web request when user names are reused across many requests?','A request identifier carried by every event of that request','A request-specific shared key separates different requests more precisely than a reused account name.', [('The same user alone with no time constraints','A reused user can merge separate activity into a single large group.'),('A different random value on every event','Unique-per-event values provide no shared correlation key.'),('The event message length','Unrelated events can have the same message length.')],['transaction'])
case('3.2','Checkout events consistently carry basket_id. Group events sharing that field.','transaction basket_id','A field named in transaction is used to connect related events into grouped results.', [('transaction count(basket_id)','The grouping key is a field, not a count aggregation.'),('eval basket_id=count','Assignment does not group events.'),('where basket_id=basket_id','A self-comparison does not create groups.')],['transaction'])
case('3.2','Two unrelated clients both have session_id=17. Every event has client_id and session_id, and a group must match both values exactly.','Use stats count by client_id session_id for the required composite-key counts','stats with both BY fields creates a group for each distinct pair of values.', [('Use stats count by session_id','This merges the different clients sharing session_id=17.'),('Use stats count by client_id','This merges sessions belonging to the same client.'),('Use stats count','This removes both grouping dimensions.')],['stats'],'hard')
case('3.3','Related browser events must fit within an overall ten-minute period, regardless of the small gaps within it.','transaction session_id maxspan=10m','maxspan constrains the total time between the earliest and latest event of a transaction.', [('transaction session_id maxpause=10m','maxpause constrains consecutive gaps, so total duration can exceed ten minutes.'),('transaction session_id maxevents=10','maxevents limits event count rather than elapsed time.'),('transaction session_id maxspan=10h','10h permits ten hours, not ten minutes.')],['transaction'])
case('3.3','Close a user transaction whenever the gap between consecutive events exceeds five minutes.','transaction user maxpause=5m','maxpause sets the maximum interval between consecutive events in a transaction.', [('transaction user maxspan=5m','maxspan limits total duration rather than each consecutive gap.'),('transaction user maxevents=5','This sets a count limit rather than a time-gap limit.'),('transaction user maxpause=5h','This permits a five-hour gap.')],['transaction'])
case('3.3','At 10:00, 10:04, and 10:09 the same key appears. A transaction has maxspan=10m and maxpause=6m. Does this sequence violate either limit?','No; total span is nine minutes and the longest gap is five minutes','The span is last minus first, while consecutive gaps are four and five minutes.', [('Yes; adding the two gaps makes fourteen minutes','Four plus five equals nine, not fourteen.'),('Yes; maxpause measures the nine-minute total','maxpause applies to consecutive gaps rather than total duration.'),('Yes; maxspan requires exactly ten minutes','maxspan is a maximum, not an exact-duration requirement.')],['transaction'])
case('3.4','A completed purchase should start with action=begin and end with action=complete. The shared key is basket_id.','transaction basket_id startswith="action=begin" endswith="action=complete"','startswith and endswith define boundary conditions for transaction formation.', [('search action=begin action=complete','A single-valued action cannot simultaneously equal both values, and this does not group events.'),('transaction action','Grouping by action separates begin and complete rather than correlating them by basket.'),('eval action="complete"','This replaces the action field without defining transaction boundaries.')],['transaction'],'hard')
case('3.4','An investigator forms transactions by request_id and then needs only groups with duration greater than 30 seconds.','transaction request_id | where duration>30','duration is generated by transaction and can then be filtered by where.', [('where duration>30 | transaction request_id','The generated transaction duration does not exist before transaction in this scenario.'),('transaction duration','This groups by a duration field rather than filtering the grouped requests.'),('fillnull value=30 duration','This fills missing values rather than selecting slow groups.')],['transaction','where'])
case('3.5','A grouped request contains five constituent events. Which generated field reports this count?','eventcount','transaction adds eventcount to report the number of events in the grouped transaction.', [('count','count is not the automatically generated transaction event-count field.'),('duration','duration is elapsed seconds, not the number of events.'),('maxspan','maxspan is a transaction constraint, not the generated event-count field.')],['transaction'])
case('3.5','A transaction starts at 12:00:05 and ends at 12:00:42. What does its generated duration represent?','37 seconds','duration is the difference in seconds between the earliest and latest constituent event times.', [('42 events','The last timestamp is not an event count.'),('37 minutes','The timestamps differ by 37 seconds, not minutes.'),('The sum of every event timestamp','duration is a difference, not a sum of epoch timestamps.')],['transaction'])
case('3.5','After grouping web sessions, an analyst needs mean transaction duration by host.','transaction session_id | stats avg(duration) by host','transaction creates duration, and stats aggregates those durations by host.', [('stats avg(duration) by host | transaction session_id','The scenario has no transaction duration before grouping.'),('transaction session_id | stats sum(eventcount) by host','This totals constituent events rather than mean duration.'),('transaction session_id | eval duration=host','This overwrites the duration rather than reporting its mean.')],['transaction','stats'])
case('3.6','A large dataset needs only the number of events per request_id; raw grouped events and boundary conditions are unnecessary.','stats count by request_id','stats is appropriate for aggregate-only grouping and avoids retaining raw events as transactions.', [('transaction request_id with no further aggregation','This retains transaction details unnecessary for the requested count table.'),('eval request_id=count','This assignment is not aggregation.'),('fillnull value=0 request_id','This replaces missing keys rather than computing counts.')],['stats','transaction'])
case('3.6','An investigator must inspect the combined raw events for each request with start/end boundary rules.','Choose transaction with the appropriate key and boundary conditions','transaction is designed for grouped event inspection and constraints such as startswith and endswith.', [('Choose only stats count by request_id','A count table loses the raw grouped events and does not apply those boundary rules.'),('Choose timechart count','A time histogram does not build bounded request groups.'),('Choose field aliasing','Aliases expose field names; they do not correlate event sequences.')],['transaction','stats'])
case('3.6','All events have a reliable session_id; only earliest time, latest time, and elapsed seconds per session are required.','stats min(_time) as first max(_time) as last by session_id | eval elapsed=last-first','With an explicit reliable key, stats can compute the required endpoints and eval their difference.', [('stats count by session_id','Counts alone do not expose the time endpoints.'),('eval elapsed=_time-_time','Each event subtracts its timestamp from itself, producing zero.'),('timechart avg(_time)','A bucketed mean timestamp is not a per-session elapsed duration.')],['stats','eval'],'hard')
case('4.1','A log has variable surrounding text but a stable marker account= followed by a username. Which FX method should be investigated first?','Regular expression extraction','The regex method uses text patterns and sample values to extract fields from unstructured events.', [('Delimiter extraction based on a fixed column number','Variable surrounding text can shift column positions.'),('A field alias without an extracted source field','An alias cannot identify a substring in raw text.'),('A transaction boundary','Transaction grouping is unrelated to extracting a username.')])
case('4.1','A generated FX regex matches one login event. What should happen before saving it for the whole source type?','Validate it against representative events and add counterexamples for incorrect matches','FX validation checks whether the extraction generalizes beyond the selected example.', [('Save immediately because one match proves universal correctness','One sample does not establish correctness across varied events.'),('Change every raw event to match the regex','Search-time extraction should accommodate the data rather than rewrite indexed events.'),('Replace the extraction with a macro count','A count macro does not validate field extraction.')])
case('4.1','The regex user=(?<account>[^ ]+) matches user=aya action=login. What field and value does it extract?','account=aya','The named capture group account contains the non-space characters after user=.', [('user=account','The capture name is account, not the literal value account.'),('account=action=login','The character class stops at the first space.'),('No field because named groups are not supported','Named capture groups are used for regex field extraction.')],['rex'])
case('4.1','An FX extraction intended for usernames also captures values in unrelated service messages. What is the most useful refinement?','Add a distinguishing required-text pattern and test both positive and negative samples','Contextual text can limit extraction to the intended events; counterexamples expose overly broad matches.', [('Make the pattern match every event unconditionally','This broadens the false matches.'),('Rename the field without changing the regex','A different field name does not fix incorrect matches.'),('Set a longer transaction maxspan','Transaction duration does not affect the extraction pattern.')],difficulty='hard')
case('4.1','A saved field extraction is private, but other users in the app need to use the field. What should the owner inspect?','The extraction permissions and app sharing scope','Saved extractions are knowledge objects whose visibility depends on permissions and context.', [('The chart span argument','Bucket size does not control extraction visibility.'),('Only the username text length','Value length does not determine knowledge-object sharing.'),('The browser zoom setting','Zoom changes appearance rather than permissions.')])
case('4.2','Events consistently use timestamp|user|action|dest. Which FX method suits these fixed-position records?','Delimiter extraction using the pipe separator','Delimiter extraction identifies ordered fields separated by a common character.', [('Delimiter extraction using a comma separator','Commas do not separate the fields in these events.'),('A tag on the whole raw event','Tags label field-value pairs and do not split columns.'),('A workflow POST body','A workflow action is not a field-extraction method.')])
case('4.2','FX delimiter extraction finds four columns. Their generated names do not describe the data. What should be done next?','Rename the extracted fields to their semantic names before saving','The delimiter workflow lets the user name the separated fields so searches can use meaningful identifiers.', [('Keep all columns under one identical field name','Repeated identical names do not describe the distinct columns.'),('Use maxpause to assign column names','maxpause is a transaction option.'),('Delete the field values from raw events','Renaming extracted fields does not require deleting data.')])
case('4.2','A team changes records from time,user,action to time,action,user. Why should a fixed-position extraction be revalidated?','The positional meaning changed even though the delimiter stayed the same','Delimiter extraction depends on field order as well as the separator.', [('Delimiter extraction infers every field meaning regardless of order','A delimiter does not encode the semantic identity of each position.'),('The comma now becomes a timechart command','A record delimiter has no such command meaning.'),('A field alias automatically detects column swaps','An alias assumes its source field already has the intended value.')])
case('4.2','An analyst sees unstructured messages with optional phrases and inconsistent whitespace. Why might delimiter extraction be unsuitable?','The required field does not occupy a stable delimited position','Positional splitting is reliable when record structure and delimiter use are consistent.', [('Delimiter extraction cannot process any structured data','Structured data with consistent separators is its intended use.'),('Delimiter extraction requires CIM acceleration','No CIM acceleration prerequisite exists.'),('The destination field is numeric','Value type alone does not prevent positional extraction.')])
case('4.2','Before saving a delimited extraction for a source type, which evidence best supports its reliability?','Samples with different values retain the same delimiter and field order','A stable layout across representative records supports the positional extraction.', [('A single record has a recognizable username','One recognizable value does not establish consistent layout.'),('The source type name is short','Name length does not validate record structure.'),('The dashboard has a dark theme','Visual theme does not validate field extraction.')])
case('5.1','A vendor extracts client_ip, but reports expect src. Both names should remain usable.','Create a field alias from client_ip to src','Field aliasing exposes the source value under an additional field name while retaining the original.', [('Rename client_ip to src in every report','rename changes the name in that pipeline rather than exposing both names through a reusable alias.'),('Create a tag called src','Tags do not create a new field containing the IP value.'),('Set src to the literal string client_ip','A literal string is not the original field value.')])
case('5.1','Two source types use client_ip and remote_addr for the same source-address concept. A report should use src.','Configure source-type-appropriate aliases to src','Aliases normalize equivalent field names within the appropriate knowledge-object scope.', [('Alias every unrelated field to src','Only fields with equivalent meaning should map to src.'),('Use src as a tag value instead of a field','A tag label does not provide a normalized source-address field.'),('Delete both extracted fields','Deleting the input values prevents meaningful normalization.')])
case('5.1','A proposed field alias must lowercase usernames before exposing the result as user. Is aliasing alone appropriate?','No; use a calculated field for the value transformation','An alias changes how a value is named, while an eval-based calculation can transform the value.', [('Yes; aliases always lowercase every value','Aliases do not automatically transform case.'),('Yes; the alias name is an eval expression','The alias target is a field name, not a transformation expression.'),('No; usernames cannot be processed at search time','Search-time eval can process username strings.')],['eval'])
case('5.1','A lookup produces asset_owner after field aliasing. A proposed alias asset_owner AS owner does not work at the earlier aliasing stage. Why?','The source field is created later in the search-time operation sequence','Field aliases cannot use fields added by later operations such as lookups.', [('Aliases run only at index time','Field aliases are search-time knowledge objects.'),('asset_owner contains an underscore','Underscores are permitted in field names.'),('All lookup fields are numeric','Lookups can add string fields too.')],difficulty='hard')
case('5.1','A reusable alias for a vendor-specific field is visible in one app but absent in another. What should be checked first?','The alias sharing scope and app context','Knowledge-object visibility depends on its permissions and sharing context.', [('The eventcount value','eventcount does not determine alias permissions.'),('The browser operating system','The OS is not the sharing configuration.'),('The timechart color palette','Visualization colors do not control aliases.')])
case('5.2','Every web search repeats eval kib=bytes/1024. The team wants kib automatically available for that source type.','Define kib as a calculated field with bytes/1024','A calculated field reuses an eval expression at search time rather than repeating it in each search.', [('Create a field alias bytes AS kib','An alias preserves the byte value and does not divide it.'),('Create an event type named kib','An event type classifies events instead of doing arithmetic.'),('Create a workflow GET action','A GET action opens a URL rather than calculating a numeric field.')],['eval'])
case('5.2','A normalized user field should contain lower(account) for a source type. Which reusable knowledge object fits?','A calculated field using lower(account)','Calculated fields use eval expressions, including string transformations.', [('A field alias named lower(account)','An alias name does not execute the lower function.'),('A tag named lower','A tag labels values rather than calculating field values.'),('A transaction on account','Grouping accounts does not lowercase them.')],['eval'])
case('5.2','A field alias exposes client_ip as src. A calculated field subsequently uses src in an expression. Why is this sequence viable?','Field aliasing precedes calculated fields in search-time processing','An aliased field can be available as an input to a subsequent calculated field.', [('Calculated fields always run before aliases','The operation order is the opposite.'),('Aliases and calculated fields modify raw indexed data','Both are search-time operations.'),('The expression works only in a timechart','The operation order does not require a timechart.')],['eval'],'hard')
case('5.2','A calculated field depends on department, but department is only added by an automatic lookup later in the sequence. What is the problem?','The lookup output is unavailable when the calculated field is evaluated','Calculated fields precede lookups, so they cannot rely on values created by a later automatic lookup.', [('Calculated fields cannot perform string operations','They can use eval string functions.'),('Lookups cannot add department values','Lookups can add department fields; the issue is timing.'),('department must be a transaction key','No such restriction applies.')],difficulty='hard')
case('5.2','Two calculated fields in the same source-type configuration depend on each other in sequence. Should their evaluation be treated as a guaranteed chain?','No; avoid chaining search-time calculated fields that depend on each other','Search-time calculated fields are evaluated independently, so another calculated field is not a dependable input.', [('Yes; their display order always guarantees dependencies','Their display order does not establish a guaranteed chain.'),('Yes; naming one A and the other B guarantees order','Alphabetical names do not make this dependency reliable.'),('No; eval cannot calculate more than one field','eval in a search pipeline can calculate fields; this concerns reusable calculated-field dependencies.')],['eval'],'hard')
case('6.1','Several host values belong to the same production group. An analyst wants a readable label on those host=value pairs.','Assign the production tag to the relevant host values','Tags label field-value pairs, allowing a common label across distinct values.', [('Replace every host value with production','This loses the individual host identities.'),('Set transaction maxspan=production','maxspan requires a time constraint, not a tag label.'),('Use a calculated field to erase host','Erasing the host does not preserve the grouping labels.')])
case('6.1','A tag called critical is assigned to selected host values. Search specifically for events tagged critical on the host field.','tag::host=critical','The tag::field syntax restricts the tag match to a particular field.', [('host=critical','This matches the literal host value critical rather than its tag.'),('tag::critical=host','This reverses the field and tag label.'),('eval host="critical"','Assignment does not search tagged hosts.')],['search'])
case('6.1','One host value is labelled both production and payment. What does this mean?','The same field-value pair can carry multiple tags','Tags provide flexible labels; a value can participate in more than one logical grouping.', [('Only the most recently added tag can exist','Tags are not limited to one label per pair.'),('The raw host value becomes payment','Applying a tag does not rename the raw field value.'),('The event must be duplicated in the index','Tagging is a search-time classification and does not require duplicate indexing.')])
case('6.2','An event type called ssh_failure is defined by sourcetype=linux_secure action=failure. When does a matching event receive that classification?','At search time when the event matches the event-type definition','Event types associate matching search results with reusable event classifications.', [('Only when the event is reindexed','Event-type classification does not require reindexing.'),('Only when the raw text contains ssh_failure','The type name need not be present in raw text.'),('Only after timechart creates a bucket','Timechart is not a prerequisite for event-type matching.')])
case('6.2','An event satisfies both privileged_login and remote_login event types. What is the expected classification behavior?','It can have both values in the multivalue eventtype field','Events can match multiple event types rather than belonging to only one exclusive category.', [('The second match causes the event to be discarded','Matching multiple event types does not discard an event.'),('Only one event type can ever match','Event types are not mutually exclusive.'),('The raw event splits into two indexed records','Classification does not duplicate indexed records.')])
case('6.2','Find events classified by an existing event type named maintenance_error.','eventtype=maintenance_error','The eventtype field can be searched by the name of the saved classification.', [('tag::maintenance_error=eventtype','This reverses a tag-field relationship and does not request that event type.'),('eval eventtype="maintenance_error"','This assigns a label rather than filtering by the existing classification.'),('transaction maintenance_error','This treats the type name as a grouping field.')],['search'])
case('6.2','A team only wants to shorten a reusable SPL pipeline with stats and parameters. What should it use rather than an event type?','A search macro','Macros can expand reusable SPL chunks, including commands and arguments; event types classify matching events.', [('An event type containing piped stats','Pipes after the base search are not permitted in an event-type definition.'),('A tag containing the full pipeline','A tag label is not an executable SPL chunk.'),('A field alias containing the pipeline','An alias exposes another field name rather than a search pipeline.')])
case('6.3','Choose a valid base definition for an event type that identifies denied firewall events.','sourcetype=firewall action=denied','An event-type definition uses a matching base search without a piped transformation.', [('sourcetype=firewall | stats count','This contains a pipe and aggregate command.'),('sourcetype=firewall [search index=other]','An event-type definition cannot include a subsearch.'),('| savedsearch denied_report','Referencing a saved report this way is not a valid event-type definition.')])
case('6.3','An event-type definition uses tag=production. Why should the designer revise it?','Event types are processed before tags and their definitions cannot reference tags','The operation sequence prevents using tags as inputs to event-type definitions.', [('Tags are always raw indexed fields','Tags are search-time knowledge labels.'),('production is too long to be a tag','The issue is not label length.'),('Event types are only available for numeric data','They classify arbitrary matching events.')],difficulty='hard')
case('6.3','Before sharing an event type for successful logins, what is the strongest validation step?','Run its base search and inspect both matching and excluded login examples','The definition should select the intended events without accidentally including failures or unrelated messages.', [('Check only that the type name is unique','A unique name does not establish correct classification.'),('Add a stats pipe to guarantee validity','A piped search is unsuitable as an event-type definition.'),('Change all action values to success','Rewriting values hides mistakes instead of validating classification.')])
case('7.1','A team repeats a filter plus eval pipeline in many reports and wants one reusable SPL definition.','Create a search macro','A macro expands a reusable chunk of SPL in the search that invokes it.', [('Create a field alias','Aliases expose field names rather than SPL pipelines.'),('Create a tag','Tags label field-value pairs rather than executable search text.'),('Create a data model field named after the pipeline','A field name does not expand to a search definition.')])
case('7.1','Does a macro definition have to be an entire search from an index through a final report?','No; it may be a reusable fragment of SPL','Macros can represent search terms, expressions, or commands as well as larger search chunks.', [('Yes; every macro must begin with index=','Partial SPL definitions are allowed.'),('Yes; every macro must end with stats','There is no mandatory ending command.'),('No; macros are only literal field values','Macros expand SPL text, not just field values.')])
case('7.2','A zero-argument macro named web_filter has been created. Invoke it before a stats command.','`web_filter` | stats count','Backticks identify a search macro invocation in SPL.', [('"web_filter" | stats count','Double quotes make a literal search term rather than invoke the macro.'),('$web_filter$ | stats count','Dollar tokens are not the macro invocation syntax.'),('web_filter() | stats count','An unquoted function-like expression is not a macro invocation.')])
case('7.2','A user sees an unknown-macro error for a definition that another user can use. What is a useful first check?','The macro name, app context, and read permissions','Macros are knowledge objects; the calling search needs access to the definition in its context.', [('The number of events in the index','An inaccessible definition can fail before event searching.'),('The chart legend position','Display settings do not resolve a macro definition.'),('The browser font','Font selection does not control macro visibility.')])
case('7.3','A macro takes two arguments called idx and status_code. How should its configured name represent the argument count?','web_status(2)','The parenthesized count in a macro definition name identifies its number of required arguments.', [('web_status(idx,status_code)','The configured name uses the count, while argument names are entered separately.'),('web_status[2]','Square brackets are not the macro definition count syntax.'),('web_status(0)','Zero declares no arguments rather than two.')])
case('7.3','A macro definition needs to insert the value of its argument idx into index selection.','index=$idx$','Argument tokens use dollar signs on both sides of the argument name within a macro definition.', [('index=idx','This uses idx literally rather than substituting the argument.'),('index=`idx`','Backticks invoke a macro; they do not reference this argument.'),('index=%idx%','Percent delimiters are not macro argument tokens.')])
case('7.3','A macro has arguments idx and cutoff. The author configures Arguments as idx,cutoff,idx. What is wrong?','Argument names must not repeat','Arguments are a comma-separated list of unique names used by tokens in the definition.', [('Arguments must be numbers only','Names can be alphanumeric and include supported underscores and dashes.'),('Macros cannot have two arguments','Macros can take multiple arguments.'),('Arguments must be separated by pipe characters','The argument list uses commas rather than pipes.')])
case('7.4','A macro failed_auth(1) takes source_index. Call it with the auth index.','`failed_auth(auth)`','The invocation supplies the value in parentheses inside backticks; the definition name carries the argument count.', [('`failed_auth(1)`','This passes the literal value 1 rather than the auth index.'),('failed_auth="auth"','This is a search expression, not a macro invocation.'),('`failed_auth`(auth)','The argument list must be inside the invocation backticks.')])
case('7.4','A macro web_status(2) declares idx,status_code in that order. Invoke it with index web and code 503.','`web_status(web,503)`','Argument values are passed in the order declared by the macro definition.', [('`web_status(503,web)`','This reverses the declared index and status arguments.'),('`web_status(web)`','The second required argument is missing.'),('`web_status(2)`','The count belongs to the definition name; this call supplies only the literal 2.')])
case('7.4','A macro accepts a positive numeric cutoff. How can the author provide a helpful error for invalid values?','Define an argument validation expression and a validation error message','Macro argument validation can test supplied values and report why they are unacceptable.', [('Rely on a field alias to validate arguments','Field aliases are unrelated to macro argument validation.'),('Set transaction maxevents to the macro name','This is not a macro validation mechanism.'),('Remove every argument from the definition','That removes the parameterized behavior instead of validating it.')],difficulty='hard')
case('8.1','Clicking an IP in an event should open an external information page using a URL query parameter. Which workflow action type fits?','GET','GET workflow actions construct a URL and open it, including substituted event-field values.', [('POST','POST submits fields in an HTTP form body rather than the requested URL-query retrieval.'),('Search','A Search workflow action runs a Splunk search rather than fetching an external URL.'),('Field alias','An alias supplies a field name rather than a clickable workflow.')])
case('8.1','An external ticket endpoint expects an HTTP form submission with host and message in its body. Which action should be configured?','POST','POST workflow actions send configured key/value parameters as form data to an external endpoint.', [('GET','GET puts parameters in a URL and does not perform the requested form-body submission.'),('Search','Search actions run SPL rather than submit that form.'),('Tag','A tag classifies values rather than make an HTTP request.')])
case('8.1','A host field menu should open a new Splunk search for that host over the surrounding incident period.','Search workflow action','Search actions use event context to run an investigative Splunk search.', [('GET action to an unrelated inventory page','An inventory page is not the requested Splunk search.'),('POST action to a helpdesk API','Submitting a ticket is not the requested investigation search.'),('Calculated field','A calculated field computes values rather than launch a search.')])
case('8.2','A GET URL template is https://inventory.example/lookup?host=$host$. The selected event has host=app02. What does the token supply?','The event field value app02','Workflow tokens written as $fieldname$ are substituted with the selected event field value.', [('The literal text $host$ in every case','The token is intended to substitute the field value.'),('The name of the operating-system user','host refers to the event host field, not the desktop user.'),('The complete raw event without configuration','The host token does not mean _raw.')])
case('8.2','A GET action should only appear when the src field is available. What should be configured?','The workflow action field applicability for src','Field-based applicability makes the action available in the relevant field context.', [('An eventcount of zero','Transaction counts do not define action field applicability.'),('A macro called GET','A macro name does not configure the action menu.'),('A data model numeric type','Data model attribute type does not configure workflow visibility.')])
case('8.2','A workflow URL includes an event field value with spaces and special characters. What handling should the designer consider?','The action performs URL escaping for substituted field values by default','GET workflow substitution applies URL escaping so field values can be passed as URL components.', [('Raw field values must always be inserted without escaping','Unescaped special characters can alter the URL structure.'),('The field is automatically hashed instead of substituted','URL escaping is not hashing.'),('Every value is replaced by the field name','The event value is substituted, not only the name.')],difficulty='hard')
case('8.3','A POST ticket action needs the external parameter asset to contain the event host field. What parameter mapping fits?','asset = $host$','POST parameter names belong to the receiving form, while field tokens supply event-specific values.', [('host = "asset"','This sends a literal asset value under the wrong parameter.'),('asset = host','Without a token this does not substitute the host field value.'),('asset = `host`','Backticks are for macro invocation rather than workflow field substitution.')])
case('8.3','A form endpoint requires separate user, host, and summary parameters. Can one POST action carry them?','Yes; configure multiple key/value POST arguments','A POST workflow action can define multiple form parameters for one submission.', [('No; one workflow action may only submit one parameter','Multiple key/value arguments are supported.'),('Only if each parameter becomes a separate data model','Data models are not required for form parameters.'),('Only if all fields are concatenated into the URL','POST parameters need not be collapsed into URL query text.')])
case('8.4','A Search workflow action must investigate the clicked event host. Which search template uses that context?','index=web host="$host$"','The host field token supplies the event host to the search template.', [('index=web host="host"','This searches the literal value host.'),('index=web host="*"','A wildcard searches all hosts rather than the clicked one.'),('index=web host="$user$"','The user token supplies a different event field.')])
case('8.4','An investigator launches a Search action from an old incident. Why should the search time-range settings be inspected?','A mismatched time range can exclude relevant events even when the substituted host is correct','The search template and its time scope both influence which related events are returned.', [('Search workflow actions ignore all time ranges','Time-range configuration influences the search.'),('The event host is automatically reindexed','Launching a workflow does not reindex the event.'),('A valid host guarantees results for every time range','Relevant host activity can fall outside the selected range.')])
case('9.1','A business analyst wants to build a report in Pivot without authoring its SPL. What defines the data and available fields?','The selected data model dataset','Pivot uses the model dataset and its fields to generate the search behind the report.', [('The desktop wallpaper','Desktop appearance does not define Pivot data.'),('Only the chart color palette','Colors do not define dataset constraints or fields.'),('A workflow URL','A workflow link is not the Pivot dataset definition.')])
case('9.1','A data model has a root Web dataset and a FailedRequests child. What should selecting the child in Pivot do?','Use the parent data narrowed by the child constraints','A child dataset represents a subset of its parent dataset and inherits its constraints.', [('Include every event regardless of the parent constraints','A child retains its inherited constraints.'),('Duplicate all parent events at index time','Selecting a dataset does not duplicate indexed events.'),('Remove every inherited field','Child datasets inherit parent fields.')])
case('9.1','A Pivot table groups by service and sums bytes. What happens behind the graphical configuration?','Splunk generates a search using the dataset and requested aggregations','Pivot configurations become searches that aggregate the selected modeled data.', [('The browser invents synthetic events','Pivot operates on the modeled Splunk data.'),('The data model rewrites every raw event','The model is a search-time mapping rather than a raw rewrite.'),('No search is needed for any Pivot result','Searches produce the table and visualization data.')])
case('9.2','A model attribute bytes represents quantities and will be summed in Pivot. Which field type fits?','Number','Numeric attributes allow meaningful arithmetic and numeric aggregation.', [('Boolean','A Boolean describes true/false rather than byte quantities.'),('String because every raw event is text','The modeled type should reflect the field semantics.'),('IP address','Byte quantities are not network addresses.')])
case('9.2','An extracted destination field is defined in a parent dataset. What happens to it in a child dataset?','It is available as an inherited field','Child datasets inherit parent fields; new child fields can extend that set.', [('It must be re-extracted independently in every child','Inheritance makes the field available without independent redefinition.'),('It is deleted from the parent','Creating a child does not remove parent fields.'),('It becomes a macro argument','Field inheritance does not convert fields to macro arguments.')])
case('9.2','A helper calculated field should support another model calculation but not clutter the Pivot field choices.','Mark the helper field hidden for the relevant dataset','Hidden fields remain in the dataset definition but are not offered to Pivot users in that context.', [('Delete the helper even though another calculation needs it','Deleting it can remove the needed dependency.'),('Rename every user field to the helper name','This destroys useful field distinctions.'),('Set the helper as a workflow GET URL','A URL action does not manage Pivot field visibility.')])
case('9.2','A dataset field is marked required. What effect can that have on event membership?','Events lacking that field are excluded from the dataset','A required field acts as an additional data constraint, rather than merely a visual indicator.', [('Every missing value automatically becomes zero','Required fields do not mean fillnull with zero.'),('Only the field label becomes bold','The setting affects inclusion, not merely typography.'),('The field is removed from every event','Required does not mean delete.')],difficulty='hard')
case('9.3','A root event dataset should include only sourcetype=linux_secure. What should its constraint use?','A base search filter such as sourcetype=linux_secure','Root event datasets use simple search constraints to define their event membership.', [('A piped stats count replacing all events','A root event constraint is a base filter rather than an aggregate search pipeline.'),('A GET URL to a Linux manual','An external URL is not a dataset search constraint.'),('A chart palette called linux_secure','A palette does not select event data.')])
case('9.3','A Login child of LinuxEvents should contain only failed logins. LinuxEvents already limits sourcetype.','Add action=failure as the child constraint','The child inherits the parent source-type constraint and adds its own narrower condition.', [('Replace the parent constraint with index=*','This broadens data rather than narrowing the inherited set.'),('Delete the action field','Removing the field prevents applying the intended condition.'),('Add fillnull as the only child definition','Filling nulls does not express the failed-login subset.')])
case('9.3','Before creating a model for a new application log source, what knowledge is essential?','Understand source semantics, relevant event subsets, and useful attributes','A model maps domain knowledge onto datasets and fields, so its structure must reflect the actual data.', [('Only know the desired chart background','Appearance does not establish dataset semantics.'),('Only count the characters in the app name','Name length does not determine model structure.'),('Only enable acceleration before defining data','Acceleration does not replace defining valid datasets and fields.')])
case('10.1','Windows and Linux authentication logs use different vendor field names. What is the main CIM benefit for shared reports?','A common semantic vocabulary of fields and tags for equivalent events','CIM normalization lets reports treat equivalent source concepts consistently across vendors.', [('CIM makes every vendor raw log identical','CIM can normalize at search time while preserving raw data.'),('CIM automatically deletes unsupported sources','CIM does not delete data that lacks mappings.'),('CIM replaces the entire Splunk search language','CIM supplies semantic models, not a replacement search language.')])
case('10.1','Must indexed raw machine data be rewritten to benefit from search-time CIM mappings?','No; search-time normalization can preserve raw data','CIM supports a semantic search-time schema while the original indexed machine data remains intact.', [('Yes; all original fields must be permanently deleted','Aliases and other search-time objects can preserve originals.'),('Yes; every event must be copied to a CIM-only index','A separate duplicate index is not required for search-time mapping.'),('No; no field mappings or tags are ever needed','Preserving raw data does not remove the need for correct normalization.')])
case('10.1','A new source has standard-looking field names but its action values conflict with the model vocabulary. Is name matching alone sufficient?','No; the field meaning, expected values, and dataset constraints must also match','CIM compliance concerns semantics and constraints in addition to field names.', [('Yes; identical names guarantee equivalent meaning','Fields can share a name and still have incompatible values or meaning.'),('Yes; model membership ignores tags and constraints','Dataset constraints determine membership.'),('No; all standard field names must be changed','Correct names should be retained when their meaning matches.')])
case('10.2','Which reusable content is central to the CIM Add-on?','Preconfigured data models describing standardized fields and tags','The add-on provides models and supporting tools/documentation for consistent search-time data treatment.', [('Every possible vendor-specific parser','Vendor add-ons supply source-specific extractions and mappings; CIM is not a universal parser.'),('A replacement operating-system kernel','CIM is a Splunk add-on rather than an OS component.'),('A cloud database for moving all indexed data','CIM is not an external database storage service.')])
case('10.2','A team needs to learn which fields and tags a CIM dataset expects. Where should it look?','The CIM data model reference tables and the model definition','Those references describe dataset tags, extracted/calculated fields, meanings, and expected values.', [('Only a dashboard screenshot','A screenshot does not specify all model requirements.'),('Only the vendor product logo','Branding does not define normalized fields.'),('Only a GET workflow action','A link action does not define CIM schema requirements.')])
case('10.2','Does installing the CIM Add-on automatically normalize every unsupported custom log?','No; source-specific extractions, mappings, and classifications may still be needed','The common models describe the target schema; the source must supply appropriately normalized events.', [('Yes; installation rewrites all raw messages','Installing common models does not rewrite every vendor log.'),('Yes; all field semantics are inferred perfectly','Equivalent meanings need appropriate source mappings.'),('No; CIM models cannot be used with custom sources','Custom sources can be normalized to the supported models.')])
case('10.3','A vendor emits source_ip with the same meaning as CIM src. Both names should remain available.','Map source_ip to src with a field alias in the appropriate scope','An alias normalizes an equivalent field name while preserving the original source field.', [('Map source_ip to dest merely because both are IPs','Source and destination have different semantics.'),('Create src="source_ip" as a literal','The literal name is not the address value.'),('Tag source_ip as src instead of creating the field','A tag label does not provide the normalized address field.')])
case('10.3','A custom login event has result=DENIED. Its target dataset expects action=failure for rejected authentication.','Create a semantic value mapping from DENIED to failure','Value normalization maps vendor vocabulary to the model-defined equivalent meaning.', [('Alias result to action and leave DENIED unchanged as full compliance','An alias changes the field name but does not normalize its values.'),('Map DENIED to success','This reverses the outcome semantics.'),('Remove every rejected login event','Dropping events does not normalize them.')])
case('10.3','Fields look normalized but events are absent from the intended CIM dataset. What should be checked?','Required tags, event-type matches, and other dataset constraints','Correct field names alone do not guarantee the events satisfy model inclusion conditions.', [('Only whether the browser has a dark theme','Display theme does not affect dataset membership.'),('Only the length of the src field','Address length alone does not establish model membership.'),('Whether every event has a transaction duration','Transaction duration is not a universal CIM membership requirement.')])
case('10.3','After mapping a new authentication source, how should normalization be checked?','Search the targeted model and inspect expected field values and event inclusion','Validation should confirm both the modeled event subset and the semantic correctness of its normalized fields.', [('Assume compliance because the add-on is installed','Installation does not prove this source has the right mappings.'),('Check only that one tag label exists somewhere','One label does not validate all relevant events and fields.'),('Delete the source fields and skip inspection','Removing evidence does not validate mappings.')])
# Primary documentation references. SearchReference links use Splunk's documented resource IDs.
REFS={
 '4':'https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/9.2/use-the-field-extractor-in-splunk-web/build-field-extractions-with-the-field-extractor',
 '5':'https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.2/get-started-with-knowledge-objects/the-sequence-of-search-time-operations',
 '6':'https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/9.1/event-types/about-event-types',
 '7':'https://docs.splunk.com/Documentation/Splunk/9.4.2/Knowledge/Definesearchmacros',
 '8':'https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/9.1/workflow-actions/about-workflow-actions-in-splunk-web',
 '9':'https://help.splunk.com/en/splunk-cloud-platform/manage-knowledge-objects/knowledge-management-manual/9.3.2408/build-a-data-model/about-data-models',
 '10':'https://help.splunk.com/en/data-management/common-information-model/6.2/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time'}
def generate():
    questions=[]
    for num,c in enumerate(CASES,1):
        domain=int(c['obj'].split('.')[0])
        command=c['commands'][0] if c['commands'] else None
        ref=c['reference'] or (f'https://help.splunk.com/en?resourceId=Splunk_SearchReference_{command.capitalize()}&version=splunk-9_2' if domain<4 and command else REFS[str(domain)])
        base={'domain_id':domain,'objective_id':c['obj'],'difficulty':c['difficulty'],'commands':c['commands'],'reference':ref,'review_status':'verified'}
        choices=[(c['correct'],c['reason']),*c['wrong']]
        q={**base,'id':f'SPLK-{num:03}-A','text':c['scenario']+'\nWhich answer best meets the requirement?','type':'single','correct':['A'],'options':[{'id':chr(65+i),'text':text,'explanation':why} for i,(text,why) in enumerate(choices)],'explanation':c['reason']+' '+ ' '.join(why for _,why in c['wrong'])}
        if c['difficulty']=='medium' and num%3==0: q['difficulty']='easy'
        questions.append(q)
        q={**base,'id':f'SPLK-{num:03}-B','text':c['scenario']+'\nA colleague recommends: '+c['correct']+'. Which reasoning most accurately supports this choice?','type':'single','correct':['A'],'options':[{'id':chr(65+i),'text':why if i==0 else 'The alternative '+text+' would meet the same requirement.','explanation':why} for i,(text,why) in enumerate(choices)],'explanation':c['reason']+' The alternatives fail for the specific reasons given in their explanations.'}
        questions.append(q)
        q={**base,'id':f'SPLK-{num:03}-C','text':c['scenario']+'\nSelect TWO statements that together give the appropriate solution and its justification.','type':'multiple','correct':['A','B'],'options':[{'id':'A','text':c['correct'],'explanation':c['reason']},{'id':'B','text':c['reason'],'explanation':'This states the principle that supports the appropriate solution.'}]+[{'id':chr(67+i),'text':text,'explanation':why} for i,(text,why) in enumerate(c['wrong'])],'explanation':c['reason']+' Both the solution and the justification are needed; the other proposals do not satisfy the scenario.'}
        if c['difficulty']=='medium' and num%4==0: q['difficulty']='hard'
        questions.append(q)
    objectives={o['id'] for d in json.loads((ROOT/'references'/'blueprint.json').read_text()) for o in d['objectives']}
    seen=set(); counts={i:0 for i in range(1,11)}
    for q in questions:
        QuestionInput.model_validate(q)
        assert q['objective_id'] in objectives
        fp=fingerprint(q['text']); assert fp not in seen;seen.add(fp)
        counts[q['domain_id']]+=1
    assert counts=={1:15,2:30,3:45,4:30,5:30,6:30,7:30,8:30,9:30,10:30},counts
    assert {q['objective_id'] for q in questions}==objectives
    (ROOT/'question_bank'/'questions.json').write_text(json.dumps(questions,indent=2))
    (ROOT/'question_bank'/'validation.json').write_text(json.dumps({'count':len(questions),'original_concept_cases':len(CASES),'distribution':counts,'objective_coverage':len(objectives),'structural_validation':'passed','duplicate_stems':0,'review_method':'Author review against primary Splunk references. No live Splunk execution or independent SME review. Three related learning tasks per concept case; they are not 300 independent concepts.'},indent=2))
    print('Generated and structurally validated',len(questions),'questions from',len(CASES),'concept cases')
if __name__=='__main__': generate()
